    function tick(t){if(!alive)return;const dt=Math.min(.05,last?(t-last)/1000:0);last=t;beam=Math.max(0,beam-dt);if(destination&&!won){const dx=destination.x-player.x,dy=destination.y-player.y,d=Math.hypot(dx,dy),step=245*dt;if(d<=step+1){player.x=destination.x;player.y=destination.y;destination=null;apply();}else{player.x+=dx/d*step;player.y+=dy/d*step;}}draw();if(completePending){completePending=false;onComplete({stars:errors===0&&hints===0?3:errors<4&&hints<4?2:1,score:Math.max(450,1000-errors*30-hints*35),lesson:'Observe before acting. Ground your instructions in available evidence, then break the plan into clear steps.',metrics:{Actions:state.turns,Plans:runs,Errors:errors,Hints:hints}});}if(alive)frame=requestAnimationFrame(tick);}
